const SHORTCUT_FUNC = 'F(?:[1-9]|1[0-2])\\b';
const SHORTCUT_STROKE = `(?:${SHORTCUT_COMBO}|${SHORTCUT_FUNC})`;
const SHORTCUT_CHORD = `(?:${SHORTCUT_STROKE}(?:(?:\\s+|\\s*,\\s*)${SHORTCUT_STROKE})?)`;
