  '.view-lines',
  '.cm-editor',
  '.cm-content',
  '.editor-instance',
  '.monaco-tokenized-source',
  'pre',
  'code',
  'kbd',
  'samp',
  'var',
  '.code-block',
  '.hljs',
  '.syntax-highlighted',
  '.highlight',
  '.terminal',
  '.xterm',
  '.xterm-screen',
  '.xterm-viewport',
  '.terminal-wrapper',
  'textarea',
  '[contenteditable="true"]',
  '[contenteditable=""]',
